ALTER TABLE accounts DROP CONSTRAINT accounts_role_check;
ALTER TABLE accounts ADD CHECK (role IN ('income','expense','opening','suspense','transit','exchange','unknown'));
ALTER TABLE accounts ADD COLUMN parent_id uuid;
ALTER TABLE accounts ADD COLUMN external_identifiers jsonb NOT NULL DEFAULT '{}';
ALTER TABLE accounts ADD FOREIGN KEY (ledger_id,parent_id) REFERENCES accounts(ledger_id,id) DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE preferences (ledger_id uuid PRIMARY KEY REFERENCES ledgers(id),version bigint NOT NULL CHECK(version>0),data jsonb NOT NULL);
CREATE TABLE categories (ledger_id uuid NOT NULL REFERENCES ledgers(id),id uuid NOT NULL,name text NOT NULL,kind text NOT NULL CHECK(kind IN ('income','expense')),parent_id uuid,active boolean NOT NULL,version bigint NOT NULL CHECK(version>0),PRIMARY KEY(ledger_id,id),FOREIGN KEY(ledger_id,parent_id) REFERENCES categories(ledger_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE tags (ledger_id uuid NOT NULL REFERENCES ledgers(id),id uuid NOT NULL,name text NOT NULL,active boolean NOT NULL,version bigint NOT NULL CHECK(version>0),PRIMARY KEY(ledger_id,id),UNIQUE(ledger_id,name));
CREATE TABLE sources (ledger_id uuid NOT NULL REFERENCES ledgers(id),id uuid NOT NULL,provider text NOT NULL,source_scope text NOT NULL,external_id text NOT NULL,current_version_id uuid,PRIMARY KEY(ledger_id,id),UNIQUE(ledger_id,provider,source_scope,external_id));
CREATE TABLE source_versions (ledger_id uuid NOT NULL,source_id uuid NOT NULL,id uuid NOT NULL,version bigint NOT NULL,body text NOT NULL,content_hash text NOT NULL CHECK(length(content_hash)=64),capture_kind text NOT NULL CHECK(capture_kind IN ('original','excerpt','ai_normalized','user_statement')),origin_uri text,operation_id uuid NOT NULL,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(ledger_id,id),UNIQUE(ledger_id,source_id,id),UNIQUE(ledger_id,source_id,version),FOREIGN KEY(ledger_id,source_id) REFERENCES sources(ledger_id,id),FOREIGN KEY(ledger_id,operation_id) REFERENCES operations(ledger_id,id) DEFERRABLE INITIALLY DEFERRED);
ALTER TABLE sources ADD FOREIGN KEY(ledger_id,id,current_version_id) REFERENCES source_versions(ledger_id,source_id,id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE observations (ledger_id uuid NOT NULL,source_id uuid NOT NULL,id uuid NOT NULL,kind text NOT NULL,current_version bigint NOT NULL,version bigint NOT NULL,review_note text,ignored_reason text,PRIMARY KEY(ledger_id,id),FOREIGN KEY(ledger_id,source_id) REFERENCES sources(ledger_id,id));
CREATE TABLE observation_versions (ledger_id uuid NOT NULL,observation_id uuid NOT NULL,version bigint NOT NULL,source_version_id uuid NOT NULL,record_locator text NOT NULL,payload jsonb NOT NULL,references_json jsonb NOT NULL,extractor text NOT NULL,reason text NOT NULL,operation_id uuid NOT NULL,PRIMARY KEY(ledger_id,observation_id,version),FOREIGN KEY(ledger_id,observation_id) REFERENCES observations(ledger_id,id),FOREIGN KEY(ledger_id,source_version_id) REFERENCES source_versions(ledger_id,id),FOREIGN KEY(ledger_id,operation_id) REFERENCES operations(ledger_id,id) DEFERRABLE INITIALLY DEFERRED);
ALTER TABLE observations ADD FOREIGN KEY(ledger_id,id,current_version) REFERENCES observation_versions(ledger_id,observation_id,version) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE observation_history (ledger_id uuid NOT NULL,observation_id uuid NOT NULL,version bigint NOT NULL,snapshot jsonb NOT NULL,operation_id uuid NOT NULL,PRIMARY KEY(ledger_id,observation_id,version),FOREIGN KEY(ledger_id,observation_id) REFERENCES observations(ledger_id,id),FOREIGN KEY(ledger_id,operation_id) REFERENCES operations(ledger_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE source_positions (ledger_id uuid NOT NULL,source_version_id uuid NOT NULL,record_locator text NOT NULL,kind text NOT NULL,observation_id uuid NOT NULL,PRIMARY KEY(ledger_id,source_version_id,record_locator,kind),FOREIGN KEY(ledger_id,source_version_id) REFERENCES source_versions(ledger_id,id),FOREIGN KEY(ledger_id,observation_id) REFERENCES observations(ledger_id,id));
CREATE TABLE import_batches (ledger_id uuid NOT NULL REFERENCES ledgers(id),id uuid NOT NULL,version bigint NOT NULL,name text NOT NULL,complete boolean NOT NULL,PRIMARY KEY(ledger_id,id));
CREATE TABLE batch_sources (ledger_id uuid NOT NULL,batch_id uuid NOT NULL,source_version_id uuid NOT NULL,PRIMARY KEY(ledger_id,batch_id,source_version_id),FOREIGN KEY(ledger_id,batch_id) REFERENCES import_batches(ledger_id,id),FOREIGN KEY(ledger_id,source_version_id) REFERENCES source_versions(ledger_id,id));
CREATE TABLE batch_observations (ledger_id uuid NOT NULL,batch_id uuid NOT NULL,observation_id uuid NOT NULL,PRIMARY KEY(ledger_id,batch_id,observation_id),FOREIGN KEY(ledger_id,batch_id) REFERENCES import_batches(ledger_id,id),FOREIGN KEY(ledger_id,observation_id) REFERENCES observations(ledger_id,id));
CREATE TABLE evidence_links (ledger_id uuid NOT NULL,id uuid NOT NULL,transaction_id uuid NOT NULL,observation_id uuid NOT NULL,observation_version bigint NOT NULL,account_id uuid,role text NOT NULL CHECK(role IN ('movement','context')),currency text,direction text,amount_minor minor_amount CHECK(amount_minor>0),opened_revision bigint NOT NULL,closed_revision bigint,opened_operation_id uuid NOT NULL,closed_operation_id uuid,PRIMARY KEY(ledger_id,id),FOREIGN KEY(ledger_id,transaction_id) REFERENCES transactions(ledger_id,id),FOREIGN KEY(ledger_id,observation_id,observation_version) REFERENCES observation_versions(ledger_id,observation_id,version),FOREIGN KEY(ledger_id,account_id) REFERENCES accounts(ledger_id,id),FOREIGN KEY(ledger_id,opened_operation_id) REFERENCES operations(ledger_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(ledger_id,closed_operation_id) REFERENCES operations(ledger_id,id) DEFERRABLE INITIALLY DEFERRED,CHECK((role='movement' AND account_id IS NOT NULL AND currency IS NOT NULL AND direction IN ('in','out') AND amount_minor IS NOT NULL) OR role='context'),CHECK((closed_revision IS NULL)=(closed_operation_id IS NULL)));
CREATE INDEX evidence_observation ON evidence_links(ledger_id,observation_id) WHERE closed_revision IS NULL;
CREATE INDEX evidence_transaction ON evidence_links(ledger_id,transaction_id) WHERE closed_revision IS NULL;
ALTER TABLE evidence_links ADD FOREIGN KEY(ledger_id,account_id,currency) REFERENCES accounts(ledger_id,id,currency);
CREATE TABLE transaction_identifiers (ledger_id uuid NOT NULL,namespace text NOT NULL,account_id uuid NOT NULL,event_type text NOT NULL,external_id text NOT NULL,transaction_id uuid NOT NULL,PRIMARY KEY(ledger_id,namespace,account_id,event_type,external_id),FOREIGN KEY(ledger_id,transaction_id) REFERENCES transactions(ledger_id,id),FOREIGN KEY(ledger_id,account_id) REFERENCES accounts(ledger_id,id));
CREATE TABLE fx_rates (ledger_id uuid NOT NULL,id uuid NOT NULL,from_currency text NOT NULL,to_currency text NOT NULL,on_date date NOT NULL,rate text NOT NULL,source_version_id uuid NOT NULL,record_locator text NOT NULL,recorded_revision bigint NOT NULL,operation_id uuid NOT NULL,PRIMARY KEY(ledger_id,id),UNIQUE(ledger_id,from_currency,to_currency,on_date,rate,source_version_id,record_locator),FOREIGN KEY(ledger_id,source_version_id) REFERENCES source_versions(ledger_id,id),FOREIGN KEY(ledger_id,operation_id) REFERENCES operations(ledger_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE reconciliations (ledger_id uuid NOT NULL,id uuid NOT NULL,ledger_revision bigint NOT NULL,account_id uuid NOT NULL,statement_observation_id uuid NOT NULL,statement_version bigint NOT NULL,scope_hash text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(ledger_id,id),UNIQUE(ledger_id,scope_hash,ledger_revision),FOREIGN KEY(ledger_id,account_id) REFERENCES accounts(ledger_id,id),FOREIGN KEY(ledger_id,statement_observation_id,statement_version) REFERENCES observation_versions(ledger_id,observation_id,version));

CREATE FUNCTION protect_evidence_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.closed_revision IS NOT NULL OR NEW.closed_revision IS NULL OR NEW.closed_operation_id IS NULL OR
    (to_jsonb(NEW)-'closed_revision'-'closed_operation_id')<>(to_jsonb(OLD)-'closed_revision'-'closed_operation_id') THEN
   RAISE EXCEPTION 'Evidence history can only be closed once' USING ERRCODE='23514';
 END IF; RETURN NEW; END; $$;
CREATE TRIGGER evidence_close_only BEFORE UPDATE ON evidence_links FOR EACH ROW EXECUTE FUNCTION protect_evidence_history();
CREATE TRIGGER evidence_no_delete BEFORE DELETE ON evidence_links FOR EACH ROW EXECUTE FUNCTION reject_history_mutation();
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['source_versions','observation_versions','observation_history','transaction_identifiers','fx_rates','reconciliations'] LOOP
   EXECUTE format('CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION reject_history_mutation()',t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['preferences','categories','tags','sources','source_versions','observations','observation_versions','observation_history','source_positions','import_batches','batch_sources','batch_observations','evidence_links','transaction_identifiers','fx_rates','reconciliations'] LOOP
   EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
   EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
   EXECUTE format('CREATE POLICY owned ON %I USING (EXISTS (SELECT 1 FROM ledgers WHERE id=ledger_id)) WITH CHECK (EXISTS (SELECT 1 FROM ledgers WHERE id=ledger_id))',t);
 END LOOP;
END $$;
